    npA = numpy_to_gsl_matrix_complex(np.ascontiguousarray(A))
    npB = numpy_to_gsl_matrix_complex(np.ascontiguousarray(B))
    A_size = A.size
    B_size = B.size
    if (A.shape != (A_size, A_size)) or (B.shape != (B_size, B_size)):
        raise ValueError("Matrices must be square.")
