cdef void cumsum(int* array, int len, int* result)
{
    for (int i = 0; i < len; ++i)
    {
        if (i > 0)
            result[i] += result[i - 1];
        else
            result[i] = array[i];
    }
}

def cumulative_sum(input_list):
    input_array = (ctypes.c_int * len(input_list))(*input_list)
    output_array = (ctypes.c_int * len(input_list))()
    cumsum(input_array, len(input_list), output_array)
    return [output_array[i] for i in range(len(output_array))] + [sum(input_list)]

