def cblas_dsbmv(order, uplo, n, k, alpha, A, lda, X, incX, beta, Y, incY):

c        = (ctypes.c_int * 6)()        
c[0] = order

c[1] = uplo.value

c[2] = n

c[3] = k

c[4] = ctypes.byref(alpha)

c[5] = ctypes.byref(beta)

A = (ctypes.c_double * lda)()    
X = (ctypes.c_double * (incX + (n - 1) * abs(incX)))()   
