    A[i] = A[i].real
    if incX > 0:
        for j in range(n):
            X[j] = X[j].real
    else:
        for j in range(-1 - n, 0):
            X[j] = X[incX * (j + n) - 1].real

for i in range(n):
    Y[i] = Y[i].real

ctypes.c_void_p(cblas.dsbmv)(c, c, n, k, alpha.value, A, lda, X, incX, beta.value, Y, incY)

