    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    def get_array(self):
        array = np.zeros_like(self, dtype=np.float64)
        for i in range(self.shape[0]):
            for j in range(self.shape[1]):
                array[i, j] = self[i, j]
        return array

def compute_eigen_gensymmv(A, B):
    A_mat = Mat(np.array(A))
    B_mat = Mat(np.array(B))
    A_array = A_mat.get_array()
    B_array = B_mat.get_array()
    eigenvalues = np.zeros((A.shape[0],), dtype=np.float64)
    eigenvectors = np.zeros_like(A, dtype=np.float64)
